            const paddedPayload = payloadBase64 + "==".slice((payloadBase64.length % 4) || 4);
            const decodedPayload = JSON.parse(atob(paddedPayload));
            if (decodedPayload.hasOwnProperty("exp")) {
                const currentTime = Math.floor(Date.now() / 1000);
                pm.expect(decodedPayload.exp).to.be.above(currentTime);
            } else {
                pm.expect(true).to.be.true; // no exp field, pass
