    pm.expect(jsonParseError, "JSON parse error: " + jsonParseError).to.be.null;
    pm.expect(jsonBody).to.be.an("object");
});

pm.test("Response contains expected fields (message and/or success)", function () {
    pm.expect(jsonBody).to.satisfy(function (body) {
        return body.hasOwnProperty("message") || body.hasOwnProperty("success");
    }, "Response should contain at least one of: message, success");
});

pm.test("Response does NOT expose sensitive fields (token, authToken, password, passwordHash)", function () {
    const sensitiveFields = ["token", "authToken", "password", "passwordHash"];
    sensitiveFields.forEach(function (field) {
        pm.expect(jsonBody).to.not.have.property(field);
    });
});

// ══════════════════════════════════════════════════════════════════════════════
// 3. SUCCESS MESSAGE VALIDATION
// ══════════════════════════════════════════════════════════════════════════════
pm.test("Success message is returned (message field is a non-empty string)", function () {
    if (jsonBody && jsonBody.hasOwnProperty("message")) {
        pm.expect(jsonBody.message).to.be.a("string").and.to.have.length.above(0);
    } else {
        pm.expect.fail("'message' field is missing from the response body");
    }
});

pm.test("Success field (if present) is true", function () {
    if (jsonBody && jsonBody.hasOwnProperty("success")) {
        pm.expect(jsonBody.success).to.be.true;
    } else {
        // Field is optional — pass silently
        pm.expect(true).to.be.true;
    }
});

pm.test("Message indicates a successful logout (keyword check)", function () {
    if (jsonBody && jsonBody.message) {
        const msg = jsonBody.message.toLowerCase();
        const keywords = ["logout", "logged out", "success", "signed out", "session ended"];
        const matched = keywords.some(function (kw) { return msg.includes(kw); });
        pm.expect(matched, "Message '" + jsonBody.message + "' does not contain a recognised logout keyword").to.be.true;
    } else {
        pm.expect.fail("'message' field is missing or empty — cannot validate logout keyword");
    }
});

// ══════════════════════════════════════════════════════════════════════════════
// 4. AUTHENTICATION VALIDATION
// ══════════════════════════════════════════════════════════════════════════════
pm.test("authToken was set in the environment before the request ran", function () {
    const token = pm.environment.get("authToken");
    pm.expect(token, "authToken is not set in the environment — ensure Login ran first").to.be.a("string").and.to.have.length.above(0);
});

pm.test("Authorization header was present in the request", function () {
    const authHeader = pm.request.headers.get("Authorization");
    pm.expect(authHeader, "Authorization header is missing from the request").to.be.a("string").and.to.have.length.above(0);
});

// ══════════════════════════════════════════════════════════════════════════════
// 5. TOKEN CLEANUP
// ══════════════════════════════════════════════════════════════════════════════
// Clear environment variables after a successful logout
if (pm.response.code === 200) {
    pm.environment.unset("authToken");
    pm.environment.unset("userId");
}

pm.test("authToken environment variable has been cleared after logout", function () {
    pm.expect(pm.environment.get("authToken")).to.be.undefined;
});

pm.test("userId environment variable has been cleared after logout", function () {
    pm.expect(pm.environment.get("userId")).to.be.undefined;
});

