// 7. RESPONSE BODY FIELD PRESENCE
// ══════════════════════════════════════════════════════════════════════════════
pm.test("Required fields are present and not null/undefined", function () {
    const requiredFields = ["message"];
    requiredFields.forEach(function (field) {
        pm.expect(jsonBody, "Field '" + field + "' is missing").to.have.property(field);
        pm.expect(jsonBody[field], "Field '" + field + "' is null or undefined").to.not.be.null;
        pm.expect(jsonBody[field], "Field '" + field + "' is null or undefined").to.not.be.undefined;
    });
});

// ══════════════════════════════════════════════════════════════════════════════
// 8. SECURITY CHECKS
// ══════════════════════════════════════════════════════════════════════════════
pm.test("Response body does not contain any token values", function () {
    const bodyStr = pm.response.text();
    const tokenPatterns = [
        /\"token\"\s*:/i,
        /\"authToken\"\s*:/i,
        /\"accessToken\"\s*:/i,
        /\"refreshToken\"\s*:/i,
        /\"id_token\"\s*:/i
    ];
    tokenPatterns.forEach(function (pattern) {
        pm.expect(pattern.test(bodyStr), "Response body exposes a token field matching: " + pattern).to.be.false;
    });
});

pm.test("Response body does not expose session identifiers", function () {
    const bodyStr = pm.response.text();
    const sessionPatterns = [
        /\"sessionId\"\s*:/i,
        /\"session_id\"\s*:/i,
        /\"sid\"\s*:/i
    ];
    sessionPatterns.forEach(function (pattern) {
        pm.expect(pattern.test(bodyStr), "Response body exposes a session identifier matching: " + pattern).to.be.false;
    });
});

pm.test("Response body does not contain user credentials or sensitive data", function () {
    const bodyStr = pm.response.text();
    const credentialPatterns = [
        /\"password\"\s*:/i,
        /\"passwordHash\"\s*:/i,
        /\"secret\"\s*:/i,
        /\"apiKey\"\s*:/i,
        /\"api_key\"\s*:/i
    ];
    credentialPatterns.forEach(function (pattern) {
        pm.expect(pattern.test(bodyStr), "Response body exposes sensitive data matching: " + pattern).to.be.false;
    });
});
